 Reading Models function QUBOTools.read_model(io::IO, fmt::SuperFormat)
    header = readline(io)

    if fmt.super
        @assert("SUPER" in header, "Invalid header: '$header' is not SUPER!")

        return _read_super_model(io)
    else
        return _read_regular_model(io)
    end
end Info QUBOTools.read_model  should return a  QUBOTools.Model  instance.
